import{_ as l,C as d,c as i,o as r,b0 as a,G as p,w as e,a as t}from"./chunks/framework.JcZxIv1X.js";const o="/computer-docs/assets/image-20251021152028774.BlIB4Xpl.png",c="/computer-docs/assets/image-20251021152417300.BlX8IanJ.png",b="/computer-docs/assets/image-20251021152456131.BkjqdSKI.png",m="/computer-docs/assets/image-20251021155740304.HWXBwBVs.png",u="/computer-docs/assets/image-20251021155815777.CdPunlOH.png",h="/computer-docs/assets/image-20251021165247836.D1KROHJG.png",v="/computer-docs/assets/image-20251021165650453.D9W1ExAF.png",g="/computer-docs/assets/image-20251021165706602.5Pnq4Z8Z.png",x="/computer-docs/assets/image-20251021170202586.BGuk0BSV.png",H="/computer-docs/assets/image-20251021171828905.GtUrRpgC.png",S="/computer-docs/assets/image-20251021171904024.CgdkOdNm.png",_="/computer-docs/assets/image-20251021172317013.BTMHRYTE.png",P="/computer-docs/assets/image-20251021173114896.BP1qJ5Wz.png",C="/computer-docs/assets/image-20251021173131664.C-6NUMcC.png",y="/computer-docs/assets/image-20251021173416999.Dsbiewyd.png",k="/computer-docs/assets/image-20251021173507158.y7xGxJ0N.png",q="/computer-docs/assets/image-20251021173752270.CxOCDI-E.png",D=JSON.parse('{"title":"LV003-第3章-寄存器-内存访问","description":null,"frontmatter":{"title":"LV003-第3章-寄存器-内存访问","date":"2025-10-21T11:43:29.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/assembly/assembly/chapter/126b0eeb7bd93b86081e4984","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-10-21T11:43:29.952Z","fulluuid":"6081e49847a04716adfc7c1c66abfb67","useduuid":null}},"headers":[],"relativePath":"sdoc/assembly/assembly/chapter/126b0eeb7bd93b86081e4984.md","filePath":"sdoc/01-Assembly/10-汇编语言/01-各个章节/LV003-第3章-寄存器-内存访问.md","lastUpdated":1767424849000}'),F={name:"sdoc/assembly/assembly/chapter/126b0eeb7bd93b86081e4984.md"};function U(B,s,A,X,f,E){const n=d("center");return r(),i("div",null,[s[2]||(s[2]=a('<h1 id="lv003-第3章-寄存器-内存访问" tabindex="-1">LV003-第3章-寄存器-内存访问 <a class="header-anchor" href="#lv003-第3章-寄存器-内存访问" aria-label="Permalink to &quot;LV003-第3章-寄存器-内存访问&quot;">​</a></h1><p>第 2 章中，我们主要从 CPU <strong>如何执行指令的角度</strong> 讲解了 8086CPU 的逻辑结构、形成物理地址的方法、相关的寄存器以及一些指令。这一章中，我们从 <strong>访问内存的角度</strong> 继续学习几个寄存器。</p><h2 id="_3-1-内存中字的存储" tabindex="-1">3.1 内存中字的存储 <a class="header-anchor" href="#_3-1-内存中字的存储" aria-label="Permalink to &quot;3.1 内存中字的存储&quot;">​</a></h2><p>CPU 中，用 16 位寄存器来存储一个字。<strong>高 8 位存放高位字节，低 8 位存放低位字节</strong>。在内存中存储时，由于内存单元是字节单元（一个单元存放一个字节），则一个字要用两个地址连续的内存单元来存放，这个字的低位字节存放在低地址单元中，高位字节存放在高地址单元中。比如我们从 0 地址开始存放 20000(4E20H)，这种情况如图 3.1 所示。</p><p><img src="'+o+`" alt="image-20251021152028774"></p><p>在图 3.1 中，我们用 0、1 两个内存单元存放数据 20000(4E20H)。0、1 两个内存单元用来存储一个字，这两个单元可以看作一个起始地址为 0 的 <strong>字单元</strong>（存放一个字的内存单元，由 0、1 两个字节单元组成）。对于这个字单元来说，0 号单元是低地址单元，1 号单元是高地址单元，则字型数据 4E20H 的低位字节存放在 0 号单元中，高位字节存放在 1 号单元中。同理，将 2、3 号单元看作一个字单元，它的起始地址为 2。在这个字单元中存放数据 18(0012H)，则在 2 号单元中存放低位字节 12H，在 3 号单元中存放高位字节 00H。</p><p>我们提出字单元的概念：<strong>字单元</strong>，即 <strong>存放一个字型数据(16 位)的内存单元</strong>，由两个地址连续的内存单元组成。高地址内存单元中存放字型数据的高位字节，低地址内存单元中存放字型数据的低位字节。</p><p>在以后的课程中，我们将起始地址为 N 的字单元简称为 N 地址字单元。比如一个字单元由 2、3 两个内存单元组成，则这个字单元的起始地址为 2，我们可以说这是 2 地址字单元。</p><h3 id="问题-3-1" tabindex="-1">问题 3.1 <a class="header-anchor" href="#问题-3-1" aria-label="Permalink to &quot;问题 3.1&quot;">​</a></h3><p>对于图 3.1:</p><p>(1) 0 地址单元中存放的字节型数据是什么。<code>20H</code></p><p>(2) 0 地址字单元中存放的字型数据是什么。<code>4E20H</code></p><p>(3) 2 地址单元中存放的字节型数据是多少？<code>12H</code></p><p>(4) 2 地址字单元中存放的字型数据是多少？<code>0012H</code></p><p>(5) 1 地址字单元中存放的字型数据是多少？<code>124EH</code></p><p>思考后看分析。</p><p>分析：</p><p>对于(5)，1 地址字单元，即起始地址为 1 的字单元，它由 1 号单元和 2 号单元组成，用这两个单元存储一个字型数据，高位放在 2 号单元中，即 12H，低位放在 1 号单元中，即 4EH，它们组成字型数据是 124EH，大小为：4686。</p><p>从上面的问题中我们看到，<strong>任何两个地址连续的内存单元，N 号单元和 N+1 号单元，可以将它们看成两个内存单元，也可看成一个地址为 N 的字单元中的高位字节单元和低位字节单元</strong>。</p><h2 id="_3-2-ds-和-address" tabindex="-1">3.2 DS 和 [address] <a class="header-anchor" href="#_3-2-ds-和-address" aria-label="Permalink to &quot;3.2 DS 和 [address]&quot;">​</a></h2><p>CPU 要读写一个内存单元的时候，必须先给出这个内存单元的地址，在 8086PC 中，内存地址由段地址和偏移地址组成。8086CPU 中有一个 DS 寄存器，通常用来 <strong>存放要访问数据的段地址</strong>。比如我们要读取 10000H 单元的内容，可以用如下的程序段进行：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov bx,1000H</span></span>
<span class="line"><span>mov ds,bx</span></span>
<span class="line"><span>mov al,[0]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>上面的 3 条指令将 10000H(1000:0)中的数据读到 al 中。下面详细说明指令的含义。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov al, [0]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>前面我们使用 mov 指令，可完成两种传送：① 将数据直接送入寄存器；② 将一个寄存器中的内容送入另一个寄存器。</p><p>也可以使用 mov 指令将一个内存单元中的内容送入一个寄存器中。从哪一个内存单元送到哪一个寄存器中在指令中必须指明。寄存器用寄存器名来指明，内存单元则需用内存单元的地址来指明。显然，此时 mov 指令的格式应该是：<code>mov 寄存器名，内存单元地址</code>。</p><p>“<code>[...]</code>”表示一个内存单元， “<code>[...]</code>”中的 0 表示 <strong>内存单元的偏移地址</strong>。指令执行时，<strong>8086CPU 自动取 ds 中的数据为内存单元的段地址，和偏移地址两者共同定位一个内存单元</strong>。</p><p>我们先将段地址 1000H 放入 ds，然后用 <code>mov al,[0]</code> 完成传送。mov 指令中的 <code>[]</code> 说明操作对象是一个内存单元，<code>[]</code> 中的 0 说明这个内存单元的偏移地址是 0，它的段地址默认放在 ds 中，指令执行时，8086CPU 会自动从 ds 中取出。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov bx,1000H </span></span>
<span class="line"><span>mov ds,bx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>若要用 <code>mov al,[0]</code> 完成数据从 1000:0 单元到 al 的传送，这条指令执行时，ds 中的内容应为段地址 1000H，所以在这条指令之前应该将 1000H 送入 ds。</p><p>如何把一个数据送入寄存器呢？我们以前用类似“<code>mov ax,1</code>”这样的指令来完成，从理论上讲，我们可以用相似的方式：<code>mov ds,1000H</code>，来将 1000H 送入 ds。可现实并非如此，<strong>8086CPU 不支持将数据直接送入段寄存器的操作</strong>，ds 是一个段寄存器，所以 <code>mov ds,1000H</code> 这条指令是非法的。只好先将 1000H 送入一个一般的寄存器作为中转，如 bx，再将 bx 中的内容送入 ds。（由于 8086CPU 硬件设计的问题，8086CPU 不支持将数据直接送入段寄存器）</p><h3 id="问题-3-2" tabindex="-1">问题 3.2 <a class="header-anchor" href="#问题-3-2" aria-label="Permalink to &quot;问题 3.2&quot;">​</a></h3><p>写几条指令，将 al 中的数据送入内存单元 10000H 中，思考后看分析。</p><p>分析：</p><p>怎样将数据从寄存器送入内存单元？从内存单元到寄存器的格式是：“<code>mov 寄存器名,内存单元地址</code>”，从寄存器到内存单元则是：“<code>mov 内存单元地址,寄存器名</code>”。10000H 可表示为 1000:0，用 ds 存放段地址 1000H，偏移地址是 0，则 <code>mov [0],al</code>，可完成从 al 到 10000H 的数据传送。完整的几条指令如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov bx, 1000H</span></span>
<span class="line"><span>mov ds, bx;</span></span>
<span class="line"><span>mov [0], al;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="_3-3-字的传送" tabindex="-1">3.3 字的传送 <a class="header-anchor" href="#_3-3-字的传送" aria-label="Permalink to &quot;3.3 字的传送&quot;">​</a></h2><p>前面我们用 mov 指令在寄存器和内存之间进行字节型数据的传送。因为 8086CPU 是 16 位结构，有 16 根数据线，所以，可以一次性传送 16 位的数据，也就是说可以一次性传送一个字。只要在 mov 指令中给出 16 位的寄存器就可以进行 16 位数据的传送了。比如：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov bx,1000H</span></span>
<span class="line"><span>mov ds,bx </span></span>
<span class="line"><span>mov ax,[0]    ;1000:0 处的字型数据送入 ax</span></span>
<span class="line"><span>mov [0],cx    ;cx 中的 16 位数据送到 1000:0 处</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="问题-3-3" tabindex="-1">问题 3.3 <a class="header-anchor" href="#问题-3-3" aria-label="Permalink to &quot;问题 3.3&quot;">​</a></h3><p>内存中的情况如图 3.2 所示:</p><p><img src="`+c+`" alt="image-20251021152417300"></p><p>写出下面的 7 条指令执行后寄存器 ax, bx, cx 中的值。思考后看分析。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,1000H</span></span>
<span class="line"><span>mov ds,ax</span></span>
<span class="line"><span>mov ax,[0]</span></span>
<span class="line"><span>mov bx,[2]</span></span>
<span class="line"><span>mov cx,[1]</span></span>
<span class="line"><span>add bx,[1]</span></span>
<span class="line"><span>add cx,[2]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>分析：</p>`,45)),p(n,{style:{color:"#C0C0C0"}},{default:e(()=>[...s[0]||(s[0]=[t(" 表 3.1 指令执行与寄存器中的内容(1)",-1)])]),_:1}),s[3]||(s[3]=a('<table tabindex="0"><thead><tr><th>指令</th><th>执行后相关寄存器中的内容</th><th>说明</th></tr></thead><tbody><tr><td>mov ax,1000H</td><td>ax = 1000H</td><td>-</td></tr><tr><td>mov ds, ax</td><td>ds = 1000H</td><td>前两条指令的目的是将 ds 设为 1000H</td></tr><tr><td>mov ax, [0]</td><td>ax = 1123H</td><td>1000:0 处存放的字型数据送入 ax 1000;<br>1000:1 单元存放字型数据的高 8 位：11H, <br>1000:0 单元存放字型数据的低 8 位：23H, <br>所以 1000:0 处存放的 <strong>字型数据</strong> 为 1123H。<br>指令执行时，字型数据的高 8 位送入 ah, 字型数据的低 8 位送入 al, 则 ax 中的数据为 1123H</td></tr><tr><td>mov bx, [2]</td><td>bx = 6622H</td><td>原理同上</td></tr><tr><td>mov cx, [1]</td><td>cx = 2211H</td><td>原理同上</td></tr><tr><td>add bx, [1]</td><td>bx = 8833H</td><td>原理同上</td></tr><tr><td>add cx, [2]</td><td>cx = 8833H</td><td>原理同上</td></tr></tbody></table><h3 id="问题-3-4" tabindex="-1">问题 3.4 <a class="header-anchor" href="#问题-3-4" aria-label="Permalink to &quot;问题 3.4&quot;">​</a></h3><p>内存中的情况如图 3.2 所示：</p><p><img src="'+b+`" alt="image-20251021152456131"></p><p>写出下面的指令执行后内存中的值，思考后看分析。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,1000H</span></span>
<span class="line"><span>mov ds,ax</span></span>
<span class="line"><span>mov ax,11316</span></span>
<span class="line"><span>mov [0],ax</span></span>
<span class="line"><span>mov bx,[0]</span></span>
<span class="line"><span>sub bx,[2]</span></span>
<span class="line"><span>mov [2],bx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>分析：</p><p>进行单步跟踪，看一下每条指令执行后相关寄存器或内存单元中的值，见表 3.2。</p>`,8)),p(n,{style:{color:"#C0C0C0"}},{default:e(()=>[...s[1]||(s[1]=[t(" 表 3.2 指令执行与寄存器中的内容(2)",-1)])]),_:1}),s[4]||(s[4]=a('<table tabindex="0"><thead><tr><th>指令</th><th>执行后相关寄存器中的内容</th><th>说明</th></tr></thead><tbody><tr><td>mov ax,1000H</td><td>ax = 1000H</td><td>-</td></tr><tr><td>mov ds, ax</td><td>ds = 1000H</td><td>前两条指令的目的是将 ds 设为 1000H</td></tr><tr><td>mov ax,11316</td><td>ax = 2C34H</td><td>十进制 11316，二进制 10 1100 0011 0100，十六进制 2C34H</td></tr><tr><td>mov [0], ax</td><td>10000H 34<br>10001H 2C<br>10002H 22<br>10003H 11<br></td><td>ax 中的字型数据送到 1000:0 处<br>ax 中的字型数据是 2C34H,<br>高 8 位：2CH, 在 ah 中<br>低 8 位：34H, 在 al 中<br>指令执行时，高 8 位送入高地址 1000:1 单元，低 8 位送入低地址 1000:0 单元</td></tr><tr><td>mov bx, [0]</td><td>bx = 2C34H</td><td>10000H 开始的字单元中的数据送入 bx</td></tr><tr><td>sub bx, [2]</td><td>bx = 1B12H</td><td>bx =“b 中的字型数据-1000:2 处的字型数据 = 2C34H -1122H = 1B12H”</td></tr><tr><td>mov [2], bx</td><td>10000H 34<br>10001H 2C<br>10002H 12<br>10003H 1B<br></td><td>bx 中的字型数据送到 1000:2 处</td></tr></tbody></table><h2 id="_3-4-mov、add、sub-指令" tabindex="-1">3.4 mov、add、sub 指令 <a class="header-anchor" href="#_3-4-mov、add、sub-指令" aria-label="Permalink to &quot;3.4 mov、add、sub 指令&quot;">​</a></h2><p>前面我们用到了 mov、add、sub 指令，它们都带有两个操作对象。到现在，我们知道，mov 指令可以有以下几种形式。</p><table tabindex="0"><thead><tr><th>指令</th><th>形式</th><th>例子</th></tr></thead><tbody><tr><td>mov</td><td><code>寄存器,数据</code></td><td><code>mov ax,8</code></td></tr><tr><td>mov</td><td><code>寄存器,寄存器</code></td><td><code>mov ax,bx</code></td></tr><tr><td>mov</td><td><code>寄存器,内存单元</code></td><td><code>mov ax,[0]</code></td></tr><tr><td>mov</td><td><code>内存单元,寄存器</code></td><td><code>mov [0],ax</code></td></tr><tr><td>mov</td><td><code>段寄存器,寄存器</code></td><td><code>mov ds,ax</code></td></tr></tbody></table><p>我们可以根据这些已知指令进行下面的推测。</p><p>（1）既然有“<code>mov 段寄存器,寄存器</code>”，从寄存器向段寄存器传送数据，那么也应该有“mov 寄存器, 段寄存器”，从段寄存器向寄存器传送数据。一个合理的设想是：<strong>8086CPU 内部有寄存器到段寄存器的通路，那么也应该有相反的通路</strong>。</p><p>图 3.4 中，用 A 命令在一个预设的地址 073F: 0100 处，用汇编的形式 <code>mov ax,ds</code> 写入指令，再用 T 命令执行，可以看到执行的结果，段寄存器 ds 中的值送到了寄存器 ax 中。通过验证我们知道，“<code>mov 寄存器,段寄存器</code>”是正确的指令。</p><p><img src="'+m+`" alt="image-20251021155740304"></p><p>（2）既然有“<code>mov 内存单元,寄存器</code>”，从寄存器向内存单元传送数据，那么也应该有“<code>mov 内存单元,段寄存器</code>”，从段寄存器向内存单元传送数据。比如我们可以将段寄存器 cs 中的内容送入内存 10000H 处，指令如下。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,1000H</span></span>
<span class="line"><span>mov ds,ax</span></span>
<span class="line"><span>mov [0],cs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>在 Debug 中进行试验，如图 3.5 所示。</p><p><img src="`+u+`" alt="image-20251021155815777"></p><p>图 3.5 中，当 CS: IP 指向 073F: 0105 的时候，Debug 显示当前的指令 <code>mov [0000],cs</code>，因为这是一条访问内存的指令，Debug 还显示出指令要访问的内存单元中的内容。由于指令中的 <strong>CS 是一个 16 位寄存器，所以要访问（写入)的内存单元是一个字单元</strong>，它的偏移地址为 0，段地址在 ds 中，Debug 在屏幕右边显示出“DS: 0000 = 0000”，我们可以知道这个字单元中的内容为 0。</p><p><code>mov [0000],cs</code> 执行后，CS 中的数据(073FH)被写入 1000:0 处，1000:1 单元存放 07H，1000:0 单元存放 3FH。</p><p>最后，用 D 命令从 1000:0 开始查看指令执行后内存中的情况，注意 1000:0、1000:1 两个单元的内容。</p><p>（3）“<code>mov 段寄存器,内存单元</code>”也应该可行，比如我们可以用 10000H 处存放的字型数据设置 ds(即将 10000H 处存放的字型数据送入 ds)，指令如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,1000H</span></span>
<span class="line"><span>mov ds,ax</span></span>
<span class="line"><span>mov ds,[0]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>add 和 sub 指令同 mov 一样，都有两个操作对象。它们也可以有以下几种形式：</p><table tabindex="0"><thead><tr><th>指令</th><th>格式</th><th>例子</th></tr></thead><tbody><tr><td>add</td><td><code>寄存器,数据</code></td><td><code>add ax,8</code></td></tr><tr><td>add</td><td><code>寄存器,寄存器</code></td><td><code>add ax,bx</code></td></tr><tr><td>add</td><td><code>寄存器,内存单元</code></td><td><code>add ax,[0]</code></td></tr><tr><td>add</td><td><code>内存单元,寄存器</code></td><td><code>add [0],ax</code></td></tr><tr><td>sub</td><td><code>寄存器,数据</code></td><td><code>sub ax,9</code></td></tr><tr><td>sub</td><td><code>寄存器,寄存器</code></td><td><code>sub ax,bx</code></td></tr><tr><td>sub</td><td><code>寄存器,内存单元</code></td><td><code>sub ax,[0]</code></td></tr><tr><td>sub</td><td><code>内存单元,寄存器</code></td><td><code>sub [0],ax</code></td></tr></tbody></table><ul><li><strong>add 和 sub 指令不能对段寄存器进行操作</strong>‌。这是由于硬件限制，段寄存器不能参与运算‌。</li></ul><h2 id="_3-5-数据段" tabindex="-1">3.5 数据段 <a class="header-anchor" href="#_3-5-数据段" aria-label="Permalink to &quot;3.5 数据段&quot;">​</a></h2><p>2.8 节讲过，对于 8086PC 机，在编程时，可以根据需要，将一组内存单元定义为一个段。我们可以将一组长度为 N(N≤64KB) 、地址连续、起始地址为 16 的倍数的内存单元当作专门存储数据的内存空间，从而定义了一个数据段。比如用 123B0H~123B9H 这段内存空间来存放数据，我们就可以认为，123B0H~123B9H 这段内存是一个数据段，它的段地址为 123BH，长度为 10 个字节。</p><p>如何访问数据段中的数据呢？将一段内存当作数据段，是我们在编程时的一种安排，可以在具体操作的时候，用 ds 存放数据段的段地址，再根据需要，用相关指令访问数据段中的具体单元。</p><p>比如，将 123B0H~123B9H 的内存单元定义为数据段。现在要累加这个数据段中的前 3 个单元中的数据，代码如下。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,123BH</span></span>
<span class="line"><span>mov ds,ax       ;将 123BH 送入 ds 中，作为数据段的段地址</span></span>
<span class="line"><span>mov al,0        ;用 al 存放累加结果</span></span>
<span class="line"><span>add al,[0]      ;将数据段第一个单元(偏移地址为 0)中的数值加到 al 中</span></span>
<span class="line"><span>add al,[1]      ;将数据段第二个单元(偏移地址为 1)中的数值加到 al 中</span></span>
<span class="line"><span>add al,[2]      ;将数据段第三个单元(偏移地址为 2)中的数值加到 a1 中</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="问题-3-5" tabindex="-1">问题 3.5 <a class="header-anchor" href="#问题-3-5" aria-label="Permalink to &quot;问题 3.5&quot;">​</a></h3><p>写几条指令，累加数据段中的前 3 个 <strong>字型数据</strong>，思考后看分析。</p><p>分析：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,123BH</span></span>
<span class="line"><span>mov ds,ax       ;将 123BH 送入 ds 中，作为数据段的段地址</span></span>
<span class="line"><span>mov ax,0        ;用 ax 存放累加结果</span></span>
<span class="line"><span>add ax,[0]      ;将数据段第一个字(偏移地址为 0)加到 ax 中 </span></span>
<span class="line"><span>add ax,[2]      ;将数据段第二个字(偏移地址为 2)加到 ax 中</span></span>
<span class="line"><span>add ax,[4]      ;将数据段第三个字(偏移地址为 4)加到 ax 中</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>注意，一个字型数据占两个单元，所以偏移地址是 0、2、4。</p><h2 id="_3-a-小结与检测点" tabindex="-1">3.A 小结与检测点 <a class="header-anchor" href="#_3-a-小结与检测点" aria-label="Permalink to &quot;3.A 小结与检测点&quot;">​</a></h2><h3 id="_3-1-3-5-小结" tabindex="-1">3.1~3.5 小结 <a class="header-anchor" href="#_3-1-3-5-小结" aria-label="Permalink to &quot;3.1~3.5 小结&quot;">​</a></h3><blockquote><p>（1）字在内存中存储时，要用两个地址连续的内存单元来存放，字的低位字节存放在低地址单元中高位字节存放在高地址单元中。</p><p>（2） 用 mov 指令访问内存单元，可以在 mov 指令中 <strong>只给出单元的偏移地址</strong>，此时，<strong>段地址默认在 DS 寄存器中</strong>。</p><p>（3） [address] 表示一个偏移地址为 address 的内存单元。</p><p>（4） 在内存和寄存器之间传送字型数据时，高地址单元和高 8 位寄存器、低地址单元和低 8 位寄存器相对应。</p><p>（5）mov、add、sub 是具有两个操作对象的指令。jmp 是具有一个操作对象的指令。</p><p>（6）可以根据自己的推测，在 Debug 中实验指令的新格式。</p></blockquote><h3 id="检测点-3-1" tabindex="-1">检测点 3.1 <a class="header-anchor" href="#检测点-3-1" aria-label="Permalink to &quot;检测点 3.1&quot;">​</a></h3><p>（1）在 Debug 中，用“d 0:0 lf”查看内存，结果如下。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0000:0000 70 80 F0 30 EF 60 30 E2-00 80 80 12 66 20 22 60</span></span>
<span class="line"><span>0000:0010 62 26 E6 D6 CC 2E 3C 3B-AB BA 00 00 26 06 66 88</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>下面的程序执行前，AX = 0，BX = 0，写出每条汇编指令执行完后相关寄存器中的值。</p><table tabindex="0"><thead><tr><th>指令</th><th>寄存器的值</th><th>解析</th></tr></thead><tbody><tr><td>mov ax,1</td><td>AX = 0001H</td><td>注意 ds 的设置。</td></tr><tr><td>mov ds, ax</td><td>DS = 0001H</td><td>注意 ds 的设置。</td></tr><tr><td>mov ax, [0000]</td><td>AX = <code>2662H</code></td><td>1H×16+0000H = 00010H 正好对应第二行第一个单元，把该地址起始的字型数据放入 AX</td></tr><tr><td>mov bx, [0001]</td><td>BX = <code>E626H</code></td><td>把 00011H 起始的字传入 BX</td></tr><tr><td>mov ax, bx</td><td>AX = <code>E626H</code></td><td>把 BX 中的字传入 AX</td></tr><tr><td>mov ax, [0000]</td><td>AX = <code>2662H</code></td><td>-</td></tr><tr><td>mov bx, [0002]</td><td>BX = <code>D6E6H</code></td><td>把 00012H 开始的字传入 BX</td></tr><tr><td>add ax, bx</td><td>AX = <code>FD48H</code></td><td>AX = AX+BX</td></tr><tr><td>add ax, [0004]</td><td>AX = <code>2C14H</code></td><td>AX = AX+2ECCH</td></tr><tr><td>mov ax,0</td><td>AX = <code>0000H</code></td><td>-</td></tr><tr><td>mov al, [0002]</td><td>AX = <code>00E6H</code></td><td>00012H 的低 8 位传入 al</td></tr><tr><td>mov bx,0</td><td>BX = <code>0000H</code></td><td>-</td></tr><tr><td>mov bl, [000C]</td><td>BX = <code>0026H</code></td><td>0001CH 的低八位传入 bl，即 0626H 的低位</td></tr><tr><td>add al, bl</td><td>AX = <code>000CH</code></td><td>注意，低 8 位寄存器和高 8 位寄存器都是 <strong>独立</strong> 的，低位 8 进位舍去，不会传入高 8 位</td></tr></tbody></table><p>（2）内存中的情况如图 3.6 所示。</p><p><img src="`+h+'" alt="image-20251021165247836"></p><p>各寄存器的初始值：CS = 2000H，IP = 0，DS = 1000H，AX = 0，BX = 0；</p><p>① 写出 CPU 执行的指令序列(用汇编指令写出)。</p><p>② 写出 CPU 执行每条指令后，CS、IP 和相关寄存器中的数值。</p><p>③ 再次体会：数据和程序有区别吗？如何确定内存中的信息哪些是数据，哪些是程序？</p><p>解析：</p><table tabindex="0"><thead><tr><th>指令序列</th><th>CS</th><th>IP</th><th>DS</th><th>AX</th><th>BX</th><th>说明</th></tr></thead><tbody><tr><td>初始状态</td><td>2000H</td><td>0000H</td><td>1000H</td><td>0000H</td><td>0000H</td><td>初始值</td></tr><tr><td>mov ax,6622H</td><td>-</td><td>0003H</td><td>-</td><td>6622H</td><td>-</td><td>DS: IP = 2000:0000，从 20000H 读代码，AX = 6622H</td></tr><tr><td>jmp 0ff0:0100</td><td>-</td><td>0008H</td><td>-</td><td>-</td><td>-</td><td>无条件跳转指令</td></tr><tr><td></td><td>0FF0H</td><td>0100H</td><td>-</td><td>-</td><td>-</td><td>jmp 指令执行完毕后改变 CS: IP</td></tr><tr><td>mov ax,2000H</td><td>-</td><td>0103H</td><td>-</td><td>2000H</td><td>-</td><td>0FF0H×16+0100H = 10000H，AX = 2000H</td></tr><tr><td>mov ds, ax</td><td>-</td><td>0105H</td><td>2000H</td><td>-</td><td>-</td><td>DS = 2000H</td></tr><tr><td>mov ax, [0008]</td><td>-</td><td>0108H</td><td>-</td><td>C389H</td><td>-</td><td>20008H 处的字放入 AX</td></tr><tr><td>mov ax, [0002]</td><td>-</td><td>010BH</td><td>-</td><td>EA66H</td><td>-</td><td>20002H 处的字放入 AX</td></tr><tr><td>结束状态</td><td>0FF0H</td><td>010BH</td><td>2000H</td><td>EA66H</td><td>0000H</td><td></td></tr></tbody></table><ul><li>数据和程序在计算机中都以二进制代码存放，没有区别，<strong>CS: IP 指向的就当成指令，DS: [addr] 指向的就当成数据</strong>。</li></ul><h2 id="_3-6-栈" tabindex="-1">3.6 栈 <a class="header-anchor" href="#_3-6-栈" aria-label="Permalink to &quot;3.6 栈&quot;">​</a></h2><p>在这里，我们对栈的研究仅限于这个角度：栈是一种具有特殊的访问方式的存储空间。它的特殊性就在于，最后进入这个空间的数据，最先出去。</p><p>从程序化的角度来讲，有一个标记一直指示着栈顶。</p><p>栈有两个基本的操作：<strong>入栈和出栈</strong>。入栈就是将一个新的元素放到栈顶，出栈就是从栈顶取出一个元素。栈顶的元素总是最后入栈，需要出栈时，又最先被从栈中取出。栈的这种操作规则被称为：<strong>LIFO (Last In, First Out) 后进先出</strong>。</p><blockquote><p>栈是一种具有特殊的访问方式 （<strong>LIFO(Last In, First Out)后进先出）</strong>) 的存储空间。</p></blockquote><table style="border:none;"><tbody><tr style="border:none;"><td width="50%" align="center" style="border:none;"><img src="'+v+'" style="border:none;"></td> <td width="50%" align="center" style="border:none;"><img src="'+g+'" style="border:none;"></td></tr></tbody></table><h2 id="_3-7-cpu-提供的栈机制" tabindex="-1">3.7 CPU 提供的栈机制 <a class="header-anchor" href="#_3-7-cpu-提供的栈机制" aria-label="Permalink to &quot;3.7 CPU 提供的栈机制&quot;">​</a></h2><p>现今的 CPU 中都有栈的设计，8086CPU 也不例外。8086CPU 提供相关的指令来以栈的方式访问内存空间。这意味着，在基于 8086CPU 编程的时候，<strong>可以将一段内存当作栈来使用</strong>。</p><p>8086CPU 提供入栈和出栈指令，最基本的两个是 PUSH（入栈）和 POP（出栈）。比如，push ax 表示将寄存器 ax 中的数据送入栈中，pop ax 表示从栈顶取出数据送入 ax。8086CPU 的 <strong>入栈和出栈操作</strong> 都是 <strong>以字为单位进行</strong> 的。</p><p>下面举例说明，我们可以将 10000H~1000FH 这段内存当作栈来使用。图 3.9 描述了下面一段指令的执行过程。</p><p><img src="'+x+`" alt="image-20251021170202586"></p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,0123H</span></span>
<span class="line"><span>push ax</span></span>
<span class="line"><span>mov bx,2266H</span></span>
<span class="line"><span>push bx</span></span>
<span class="line"><span>mov cx,1122H</span></span>
<span class="line"><span>push cx</span></span>
<span class="line"><span>pop ax</span></span>
<span class="line"><span>pop bx</span></span>
<span class="line"><span>pop cx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><ul><li>字型数据用两个单元存放，高地址单元存放高 8 位，低地址单元存放低 8 位。</li></ul><p>然而，上述过程会存在两个问题：</p><p>（1）CPU 如何知道 10000H~1000FH 这段空间被当作栈来使用？</p><p>（2）push、pop 在执行的时候，必须知道哪个单元是栈顶单元，可是，如何知道呢？</p><p>这不禁让我们想起另外一个讨论过的问题, 就是, CPU 如何知道当前要执行的指令所在的位置?我们现在知道答案, 那就是 CS、IP 中存放着当前指令的段地址和偏移地址。现在的问题是: CPU 如何知道栈顶的位置?显然, 也应该有相应的寄存器来存放栈顶的地址, 8086CPU 中, 有两个寄存器, <strong>段寄存器 SS</strong> 和<strong>堆栈指针寄存器 SP</strong>, 栈顶的段地址存放在 SS 中, 偏移地址存放在 SP 中。 任意时刻, SS: SP 指向栈顶元素。 push 指令和 pop 指令执行时, CPU 从 SS 和 SP 中得到栈顶的地址。</p><p>现在，我们可以完整地描述 push 和 pop 指令的功能了，例如 push ax。push ax 的执行，由以下两步完成。</p><p>（1）SP = SP-2，SS: SP 指向当前栈顶前面的单元，以当前栈顶前面的单元为新的栈顶；</p><p>（2）将 ax 中的内容送入 SS: SP 指向的内存单元处，SS: SP 此时指向新栈顶。</p><p>图3.10 描述了 8086CPU 对 push 指令的执行过程：</p><p><img src="`+H+'" alt="image-20251021171828905"></p><p>从图中我们可以看出，8086CPU 中，入栈时，<strong>栈顶从高地址向低地址方向增长</strong>。</p><h3 id="问题-3-6" tabindex="-1">问题 3.6 <a class="header-anchor" href="#问题-3-6" aria-label="Permalink to &quot;问题 3.6&quot;">​</a></h3><p>如果将 10000H~1000FH 这段空间当作栈，初始状态栈是空的，此时，SS = 1000H，SP =？思考后看分析。</p><p>分析：</p><p>SP = 0010H，如图 3.11 所示：</p><p><img src="'+S+'" alt="image-20251021171904024"></p><p>将 10000H~1000FH 这段空间当作栈段， SS = 1000H，栈空间大小为 16 字节，<strong>栈最底部的字单元地址为 1000:000E</strong>。任意时刻， SS: SP 指向栈顶，当栈中只有一个元素的时候， SS = 1000H， SP = 000EH。栈为空，就相当于栈中唯一的元素出栈， 出栈后，SP = SP+2， SP 原来为 000EH，加 2 后 SP = 10H，所以，当栈为空的时候， SS = 1000H，SP = 10H。</p><p>换一个角度看，任意时刻，SS: SP 指向栈顶元素，当栈为空的时候，栈中没有元素，也就 <strong>不存在栈顶元素，所以 SS: SP 只能指向栈的最底部单元下面的单元</strong>，该单元的偏移地素址为栈最底部的字单元的偏移地址+2，栈最底部字单元的地址为 1000:000E，所以栈空时，SP = 0010H。</p><p>接下来，我们描述 pop 指令的功能，例如 pop ax</p><p>pop ax 的执行过程和 push ax 刚好相反，由以下两步完成。</p><p>（1）将 SS: SP 指向的内存单元处的数据送入 ax 中；</p><p>（2）SP = SP+2， SS: SP 指向当前栈顶下面的单元，以当前栈顶下面的单元为新的栈顶。</p><p>图3.12 描述了 8086CPU 对 pop 指令的执行过程。</p><p><img src="'+_+'" alt="image-20251021172317013"></p><p>注意，图 3.12 中，出栈后，SS: SP 指向新的栈顶 1000EH，pop 操作前的栈顶元素，<strong>1000CH 处的 2266H 依然存在，但是，它已不在栈中</strong>。当再次执行 push 等入栈指令后，SS: SP 移至 1000CH，并在里面写入新的数据，它将被覆盖。</p><h2 id="_3-8-栈顶超界的问题" tabindex="-1">3.8 栈顶超界的问题 <a class="header-anchor" href="#_3-8-栈顶超界的问题" aria-label="Permalink to &quot;3.8 栈顶超界的问题&quot;">​</a></h2><p>8086CPU 用 SS 和 SP 指示栈顶的地址，并提供 push 和 pop 指令实现入栈和出栈。</p><p>但是，还有一个问题需要讨论，就是 SS 和 SP 只是记录了栈顶的地址，依靠 SS 和 SP 可以保证在入栈和出栈时找到栈顶。可是，如何能够保证在入栈、出栈时，栈顶不会超出栈空间？</p><p>图 3.13 描述了在执行 push 指令后，栈顶超出栈空间的情况。</p><p><img src="'+P+'" alt="image-20251021173114896"></p><p>图 3.13 中，将 10010H~1001FH 当作栈空间，该栈空间容量为 16 字节(8 字)，初始状态为空，SS = 1000H、SP = 0020H，SS: SP 指向 10020H;</p><p>在执行 8 次 push ax 后，向栈中压入 8 个字，栈满，SS: SP 指向 10010H；</p><p>再次执行 push ax: sp = sp-2，SS: SP 指向 1000EH，栈顶超出了栈空间，ax 中的数据送入 1000EH 单元处，将栈空间外的数据覆盖。</p><p>图 3.14描述了在执行 pop 指令后，栈顶超出栈空间的情况。</p><p><img src="'+C+`" alt="image-20251021173131664"></p><p>图 3.14 中，将 10010H~1001FH 当作栈空间，该栈空间容量为 16 字节(8 字)，当前状态为满，SS = 1000H、SP = 0010H，SS: SP 指向 10010H;</p><p>在执行 8 次 pop ax 后，从栈中弹出 8 个字，栈空，SS: SP 指向 10020H；</p><p>再次执行 pop ax: sp = sp+2，SS: SP 指向 10022H，栈顶超出了栈空间。此后，如果再执行 push 指令，10020H、10021H 中的数据将被覆盖。</p><p>上面描述了执行 push、pop 指令时，发生的栈顶超界问题。可以看到，当 <strong>栈满的时候再使用 push 指令入栈，或栈空的时候再使用 pop 指令出栈，都将发生栈顶超界问题</strong>。</p><p>栈顶超界是危险的，因为我们既然将一段空间安排为栈，那么在栈空间之外的空间里很可能存放了具有其他用途的数据、代码等，这些数据、代码可能是我们自己程序中的，也可能是别的程序中的（毕竟一个计算机系统中并不是只有我们自己的程序在运行）。但是由于我们在入栈出栈时的不小心，而将这些数据、代码意外地改写，将会引发一连串的错误。</p><p>我们当然希望 CPU 可以帮我们解决这个问题，比如说在 CPU 中有记录栈顶上限和栈底的寄存器，我们可以通过填写这些寄存器来指定栈空间的范围，然后，CPU 在执行 push 指令的时候靠检测栈顶上限寄存器、在执行 pop 指令的时候靠检测栈底寄存器保证不会超界。</p><p>不过，对于 8086CPU，这只是我们的一个设想（我们当然可以这样设想，如果 CPU 是我们设计的话，这也就不仅仅是一个设想）。实际的情况是，8086CPU 中并没有这样的寄存器。</p><p><strong>8086CPU 不保证我们对栈的操作不会超界</strong>。这也就是说，8086CPU 只知道栈顶在何处（由 SS: SP 指示），而不知道我们安排的栈空间有多大。这点就好像 CPU 只知道当前要执行的指令在何处（由 CS: IP 指示），而不知道要执行的指令有多少。从这两点上我们可以看出 8086CPU 的工作机理，它只考虑当前的情况：当前的栈顶在何处、当前要执行的指令是哪一条。</p><p>我们在编程的时候要自己操心栈顶超界的问题，要根据可能用到的最大栈空间，来安排栈的大小，防止入栈的数据太多而导致的超界；执行出栈操作的时候也要注意，以防栈空的时候继续出栈而导致的超界。</p><h2 id="_3-9-push、pop-指令" tabindex="-1">3.9 push、pop 指令 <a class="header-anchor" href="#_3-9-push、pop-指令" aria-label="Permalink to &quot;3.9 push、pop 指令&quot;">​</a></h2><p>前面我们一直在使用 push ax 和 pop ax，显然 push 和 pop 指令是可以在寄存器和内存（栈空间当然也是内存空间的一部分，它只是一段可以以一种特殊的方式进行访问的内存空间。）之间传送数据的。</p><p>push 和 pop 指令的格式可以是如下形式：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>push register   ;将一个寄存器中的数据入栈</span></span>
<span class="line"><span>pop register    ;出栈，用一个寄存器接收出栈的数据</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>当然也可以是如下形式：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>push 段寄存器   ;将一个段寄存器中的数据入栈</span></span>
<span class="line"><span>pop 段寄存器    ;出栈，用一个段寄存器接收出栈的数据</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>push 和 pop 也可以在内存单元和内存单元之间传送数据，我们可以：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>push 内存单元   ;将一个内存字单元处的字入栈（注意：栈操作都是以字为单位）</span></span>
<span class="line"><span>pop 内存单元    ;出栈，用一个内存字单元接收出栈的数据</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>比如：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,1000H</span></span>
<span class="line"><span>mov ds,ax   ;内存单元的段地址要放在 ds 中</span></span>
<span class="line"><span>push [0]    ;将 1000:0 处的字压入栈中</span></span>
<span class="line"><span>pop [2]     ;出栈，出栈的数据送入 1000:2 处</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>指令执行时，CPU 要知道内存单元的地址，可以在 push、pop 指令中只给出内存单元的偏移地址，段地址在指令执行时，CPU 从 ds 中取得。</p><h3 id="问题-3-7" tabindex="-1">问题 3.7 <a class="header-anchor" href="#问题-3-7" aria-label="Permalink to &quot;问题 3.7&quot;">​</a></h3><p>编程，将 10000H~1000FH 这段空间当作栈，初始状态栈是空的，将 AX、BX、DS 中的数据入栈。</p><p>分析：</p><p>代码如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,1000H</span></span>
<span class="line"><span>mov ss,ax       ;设置栈的段地址，SS=1000H，不能直接向段寄存器 SS 中送入数据，所以用 ax 中转。</span></span>
<span class="line"><span>mov sp,0010H    ;设置栈顶的偏移地址，因栈为空，所以 sp=0010H。(详见问题 3.6)</span></span>
<span class="line"><span>                ;注意，不能直接设置 ss 的偏移地址，但是可以直接设置 sp 的偏移地址</span></span>
<span class="line"><span>                ;上面的 3 条指令设置栈顶地址。编程中要自己注意栈的大小。</span></span>
<span class="line"><span>push ax</span></span>
<span class="line"><span>push bx</span></span>
<span class="line"><span>push ds</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="问题-3-8" tabindex="-1">问题 3.8 <a class="header-anchor" href="#问题-3-8" aria-label="Permalink to &quot;问题 3.8&quot;">​</a></h3><p>编程：</p><p>① 将 10000H~1000FH 这段空间当作栈，初始状态栈是空的；</p><p>② 设置 AX = 001AH，BX = 001BH；</p><p>③ 将 AX、BX 中的数据入栈；</p><p>④ 然后将 AX、BX 清零；</p><p>⑤ 从栈中恢复 AX、BX 原来的内容。</p><p>解析：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax, 1000H</span></span>
<span class="line"><span>mov ss, ax</span></span>
<span class="line"><span>mov sp, 0010H    ;初始化栈顶，栈的情况如图 3.9(a) 所示</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mov ax, 001AH</span></span>
<span class="line"><span>mov bx, 001BH    ;ax、bx 入栈，栈的情况如图 3.9(b) 所示</span></span>
<span class="line"><span></span></span>
<span class="line"><span>push ax</span></span>
<span class="line"><span>push bx</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sub ax, ax      ;将 ax 清零，也可以用 mov ax,0，</span></span>
<span class="line"><span>                ;sub ax,ax 的机器码为 2 个字节，</span></span>
<span class="line"><span>                ;mov ax,0 的机器码为 3 个字节。</span></span>
<span class="line"><span>sub bx, bx</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pop bx          ;从栈中恢复 ax、bx 原来的数据，当前栈顶的内容是 bx 中原来的内容：001BH，</span></span>
<span class="line"><span>                ;ax 中原来的内容 001AH 在栈顶的下面，所以要先 pop bx，然后再 pop ax。</span></span>
<span class="line"><span>pop ax</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p><img src="`+y+`" alt="image-20251021173416999"></p><p>从上面的程序我们看到，用栈来暂存以后需要恢复的寄存器中的内容时，出栈的顺序要和入栈的顺序相反，因为最后入栈的寄存器的内容在栈顶，所以在恢复时，要最先出栈。</p><h3 id="问题-3-9" tabindex="-1">问题 3.9 <a class="header-anchor" href="#问题-3-9" aria-label="Permalink to &quot;问题 3.9&quot;">​</a></h3><p>编程：</p><p>① 将 10000H~1000FH 这段空间当作栈，初始状态栈是空的；</p><p>② 设置 AX = 001AH，BX = 001BH;</p><p>③ 利用栈，交换 AX 和 BX 中的数据。</p><p>分析：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax, 1000H</span></span>
<span class="line"><span>mov ss, ax</span></span>
<span class="line"><span>mov sp, 0010H   ;初始化栈顶，栈的情况如图 3.9.1(a) 所示</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mov ax, 001AH</span></span>
<span class="line"><span>mov bx, 001BH   </span></span>
<span class="line"><span></span></span>
<span class="line"><span>push ax</span></span>
<span class="line"><span>push bx         ;ax、bx 入栈，栈的情况如图 3.9.1(b) 所示</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pop ax          ;当前栈顶的数据是 bx 中原来的数据：001BH，所以先 pop ax,ax=001BH</span></span>
<span class="line"><span>pop bx          ;执行 pop ax 后，栈顶的数据为 ax 原来的数据，所以再 pop bx,bx=001AH</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p><img src="`+k+`" alt="image-20251021173507158"></p><h3 id="问题-3-10" tabindex="-1">问题 3.10 <a class="header-anchor" href="#问题-3-10" aria-label="Permalink to &quot;问题 3.10&quot;">​</a></h3><p>如果要在 10000H 处写入字型数据 2266H，可以用以下的代码完成：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,1000H</span></span>
<span class="line"><span>mov ds,ax </span></span>
<span class="line"><span>mov ax, 2266H </span></span>
<span class="line"><span>mov [0], ax</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>补全下面的代码，使它能够完成同样的功能：在 10000H 处写入字型数据 2266H。</p><p>要求：不能使用“<code>mov 内存单元,寄存器</code>”这类指令，思考后看分析。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>______________</span></span>
<span class="line"><span>______________</span></span>
<span class="line"><span>______________</span></span>
<span class="line"><span>mov ax, 2266H </span></span>
<span class="line"><span>push ax</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>分析：</p><p>我们来看需补全代码的最后两条指令，将 ax 中的 2266H 压入栈中，也就是说，最终应由 push ax 将 2266H 写入 10000H 处。问题的关键就在于：如何使 push ax 访问的内存单元是 10000H。</p><p>push ax 是入栈指令，它将在栈顶之上压入新的数据。一定要注意：它的执行过程是，先将记录栈顶偏移地址的 SP 寄存器中的内容减 2，使得 SS: SP 指向新的栈顶单元，然后再将寄存器中的数据送入 SS: SP 指向的新的栈顶单元。</p><p>所以，要在执行 push ax 之前，将 SS: SP 指向 10002H（可以设 SS = 1000H，SP = 0002H), 这样，在执行 push ax 的时候，CPU 先将 SP = SP-2, 使得 SS: SP 指向 10000H，再将 ax 中的数据送入 SS: SP 指向的内存单元处，即 10000H 处。</p><p>所以完成的程序如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax, 1000H</span></span>
<span class="line"><span>mov ss, ax</span></span>
<span class="line"><span>mov sp, 0002H</span></span>
<span class="line"><span>mov ax, 2266H </span></span>
<span class="line"><span>push ax</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>从问题 3.10 的分析中可以看出，push、pop 实质上就是一种 <strong>内存传送指令</strong>，<strong>可以在寄存器和内存之间传送数据</strong>，与 mov 指令不同的是，<strong>push 和 pop 指令访问的内存单元的地址</strong> 不是在指令中给出的，而 <strong>是由 SS: SP 指出的</strong>。同时，<strong>push 和 pop 指令还要改变 SP 中的内容</strong>。</p><p>我们要十分清楚的是，push 和 pop 指令同 mov 指令不同，CPU 执行 mov 指令只需一步操作，就是传送，而执行 push、pop 指令却需要两步操作。</p><ul><li>执行 <strong>push</strong> 时，CPU 的两步操作是：<strong>先改变 SP，后向 SS: SP 处传送</strong>。</li><li>执行 <strong>pop</strong> 时，CPU 的两步操作是：<strong>先读取 SS: SP 处的数据，后改变 SP</strong>。</li></ul><p>注意，push，pop 等栈操作指令，修改的只是 SP。也就是说，栈顶的变化范围最大为：0~FFFFH。</p><p>提供：SS、SP 指示栈顶；改变 SP 后写内存的入栈指令；读内存后改变 SP 的出栈指令。这就是 8086CPU 提供的栈操作机制。</p><h2 id="_3-b-栈的综述" tabindex="-1">3.B 栈的综述 <a class="header-anchor" href="#_3-b-栈的综述" aria-label="Permalink to &quot;3.B 栈的综述&quot;">​</a></h2><p>栈是一种非常重要的机制，一定要深入理解，灵活掌握：</p><blockquote><p>(1)8086CPU 提供了栈操作机制，方案如下。</p><p>在 SS、SP 中存放栈顶的段地址和偏移地址；</p><p>提供入栈和出栈指令，它们根据 SS: SP 指示的地址，按照栈的方式访问内存单元。</p><p>(2)push 指令的执行步骤：①SP = SP - 2；② 向 SS: SP 指向的字单元中送入数据。</p><p>(3)pop 指令的执行步骤：① 从 SS: SP 指向的字单元中读取数据；②SP = SP + 2。</p><p>(4)任意时刻，SS: SP 指向栈顶元素。</p><p>(5)8086CPU 只记录栈顶，栈空间的大小我们要自己管理。</p><p>(6)用栈来暂存以后需要恢复的寄存器的内容时，寄存器出栈的顺序要和入栈的顺序相反。</p><p>(7)push、pop 实质上是一种内存传送指令，注意它们的灵活应用。</p></blockquote><h2 id="_3-10-栈段" tabindex="-1">3.10 栈段 <a class="header-anchor" href="#_3-10-栈段" aria-label="Permalink to &quot;3.10 栈段&quot;">​</a></h2><p>2.8 节讲过，对于 8086PC 机，在编程时，可以根据需要，将一组内存单元定义为一个段。我们可以将长度为 N(N≤64KB)的一组地址连续、起始地址为 16 的倍数的内存单元，当作栈空间来用，从而定义了一个 <strong>栈段</strong>。比如，我们将 10010H~1001FH 这段长度为 16 字节的内存空间当作栈来用，以栈的方式进行访问。这段空间就可以称为一个栈段，段地址为 1001H，大小为 16 字节。</p><p>将一段内存当作栈段，仅仅是我们在编程时的一种安排，CPU 并不会由于这种安排自动地将我们定义的栈段当作栈空间来访问，要在执行 push、pop 等栈操作指令时通过 SS: SP 指向我们定义的栈段。</p><h3 id="问题-3-11" tabindex="-1">问题 3.11 <a class="header-anchor" href="#问题-3-11" aria-label="Permalink to &quot;问题 3.11&quot;">​</a></h3><p>如果将 10000H~1FFFFH 这段空间当作栈段，初始状态栈是空的，此时，SS = 1000H， SP =？</p><p>解析：</p><p>如果将 10000H~1FFFFH 这段空间当作栈段，SS = 1000H，栈空间为 64KB，栈最底部的字单元地址为 1000: FFFE。任意时刻，SS: SP 指向栈顶单元，当栈中只有一个元素的时候， SS = 1000H， SP = FFFEH。栈为空，就相当于栈中唯一的元素出栈，出栈后，SP = SP+2。</p><p>SP 原来为 FFFEH，加 2 后 SP = 0，所以，当栈为空的时候，SS = 1000H，SP = 0。</p><p>换一个角度看，任意时刻，SS: SP 指向栈顶元素，当栈为空的时候，栈中没有元素，也就不存在栈顶元素，所以 SS: SP 只能指向栈的最底部单元下面的单元，该单元的地址为栈最底部的字单元的地址+2。栈最底部字单元的地址为 1000: FFFE，所以栈空时，SP = 0000H</p><h3 id="问题-3-12" tabindex="-1">问题 3.12 <a class="header-anchor" href="#问题-3-12" aria-label="Permalink to &quot;问题 3.12&quot;">​</a></h3><p>一个栈段最大可以设为多少？为什么？思考后看分析。</p><p>分析：</p><p>这个问题显而易见，提出来只是为了提示我们将相关的知识融会起来。首先从栈操作指令所完成的功能的角度上来看，push、pop 等指令在执行的时候只修改 SP，所以栈顶的变化范围是 0~FFFFH，从栈空时候的 SP = 0，一直压栈，直到栈满时 SP = 0；如果再次压栈，栈顶将环绕，覆盖了原来栈中的内容。所以一个栈段的容量最大为 64KB。</p><h2 id="_3-c-段的综述" tabindex="-1">3.C 段的综述 <a class="header-anchor" href="#_3-c-段的综述" aria-label="Permalink to &quot;3.C 段的综述&quot;">​</a></h2><blockquote><p>我们可以将一段内存定义为一个段，用一个段地址指示段，用偏移地址访问段内的单元。这完全是我们自己的安排。</p><p>我们可以用一个段存放数据，将它定义为“数据段”</p><p>我们可以用一个段存放代码，将它定义为“代码段”</p><p>我们可以用一个段当作栈，将它定义为“栈段”</p><p>我们可以这样安排，但若要让 CPU 按照我们的安排来访问这些段，就要：</p><p>对于数据段，将它的段地址放在 DS 中，用 mov、add、sub 等访问内存单元的指令时，CPU 就将我们定义的数据段中的内容当作数据来访问</p><p>对于代码段，将它的段地址放在 CS 中，将段中第一条指令的偏移地址放在 IP 中，这样 CPU 就将执行我们定义的代码段中的指令；</p><p>对于栈段，将它的段地址放在 SS 中，将栈顶单元的偏移地址放在 SP 中，这样 CPU 在需要进行栈操作的时候，比如执行 push、pop 指令等，就将我们定义的栈段当作栈空间来用。</p><p>可见，不管我们如何安排，CPU 将内存中的某段内容当作代码，是因 CS: IP 指向了那里；CPU 将某段内存当作栈，是因为 SS: SP 指向了那里。我们一定要清楚，什么是我们的安排，以及如何让 CPU 按我们的安排行事。要非常清楚 CPU 的工作机理，才能在控制 CPU 按照我们的安排运行的时候做到游刃有余。</p><p>比如我们将 10000H~1001FH 安排为代码段，并在里面存储如下代码：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax, 1000H</span></span>
<span class="line"><span>mov ss, ax mov </span></span>
<span class="line"><span>sp, 0020H        ;初始化栈顶 mov ax, cs</span></span>
<span class="line"><span>mov ds, ax       ;设置数据段段地址 </span></span>
<span class="line"><span>mov ax, [0]</span></span>
<span class="line"><span>add ax, [2]</span></span>
<span class="line"><span>mov bx, [4]</span></span>
<span class="line"><span>add bx, [6]</span></span>
<span class="line"><span>push ax</span></span>
<span class="line"><span>push bx</span></span>
<span class="line"><span>pop ax</span></span>
<span class="line"><span>pop bx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>设置 CS = 1000H，IP = 0，这段代码将得到执行。可以看到，在这段代码中，我们又将 10000H~1001FH 安排为栈段和数据段。10000H~1001FH 这段内存，既是代码段，又是栈段和数据段。</p><p>一段内存，可以既是代码的存储空间，又是数据的存储空间，还可以是栈空间，也可以什么也不是。关键在于 CPU 中寄存器的设置，即 CS、IP，SS、SP，DS 的指向。</p></blockquote><h2 id="_3-d-检测点" tabindex="-1">3.D 检测点 <a class="header-anchor" href="#_3-d-检测点" aria-label="Permalink to &quot;3.D 检测点&quot;">​</a></h2><p>(1)补全下面的程序，使其可以将 10000H~1000FH 中的 8 个字，逆序复制到 20000H~2000FH 中。逆序复制的含义如图 3.17 所示（图中内存里的数据均为假设）。</p><p><img src="`+q+`" alt="image-20251021173752270"></p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax, 1000H</span></span>
<span class="line"><span>mov ds, ax </span></span>
<span class="line"><span>_____________</span></span>
<span class="line"><span>_____________</span></span>
<span class="line"><span>_____________</span></span>
<span class="line"><span>push [0]</span></span>
<span class="line"><span>push [2]</span></span>
<span class="line"><span>push [4]</span></span>
<span class="line"><span>push [6]</span></span>
<span class="line"><span>push [8]</span></span>
<span class="line"><span>push [A]</span></span>
<span class="line"><span>push [C]</span></span>
<span class="line"><span>push [E]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>解析：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax, 2000H</span></span>
<span class="line"><span>mov ss, ax;</span></span>
<span class="line"><span>mov sp, 0010H</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>10000H~1000FH 内存空间当 <strong>数据</strong> 来访问，20000H~2000FH 内存空间当 <strong>栈</strong> 来使用。栈空时，栈顶指针应该指向 20010H，入栈时，先 SP = SP-2 = 000EH，再入栈，正好是逆序复制目标位置第一个字的地址。</p><p>（注：<code>push [0]</code> 指的是把 <code>ds:0</code> 内存单元的数据压入栈）</p><p>(2)补全下面的程序，使其可以将 10000H~1000FH 中的 8 个字，逆序复制到 20000H~2000FH 中</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax, 2000H</span></span>
<span class="line"><span>mov ds, ax </span></span>
<span class="line"><span>_____________</span></span>
<span class="line"><span>_____________</span></span>
<span class="line"><span>_____________</span></span>
<span class="line"><span>pop [E] </span></span>
<span class="line"><span>pop [C] </span></span>
<span class="line"><span>pop [A] </span></span>
<span class="line"><span>pop [8] </span></span>
<span class="line"><span>pop [6] </span></span>
<span class="line"><span>pop [4] </span></span>
<span class="line"><span>pop [2] </span></span>
<span class="line"><span>pop [0]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>解答：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    mov ax, 1000H</span></span>
<span class="line"><span>    mov ss, ax</span></span>
<span class="line"><span>    mov sp, 0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>第二小题和第一小题正好相反，将左侧 10000H~1000FH 当作栈区，右侧当作数据区。</p><p>栈满时，栈顶指针应指向 10000H，出栈时先出栈，再 SP = SP + 2 ，实现逆序复制。</p><p>（注：<code>pop [E]</code> 指的是把 <code>ds:E</code> 内存单元的数据弹出栈）</p>`,188))])}const I=l(F,[["render",U]]);export{D as __pageData,I as default};
